mapper.select:
SELECT m.member_id,m.username,m.name,TO_CHAR(m.regdate,'yyyy-mm-dd') as dbday,a.authority,m.enabled FROM member m JOIN authority a ON m.member_id=a.member_id
AND authority=#{authority}
AND enabled=#{enabled}
ORDER BY m.member_id ASC OFFSET #{start} ROWS FETCH NEXT 10 ROWS ONLY

SELECT COUNT(*)
FROM member m
JOIN authority a
ON m.member_id=a.member_id


		AND authority=#{authority}


		AND enabled=#{enabled}

SELECT Q.NO,Q.MEMBER_ID,M.NAME,Q.SUBJECT,Q.CATEGORY_NO as categoryno,C.CATEGORY, TO_CHAR(Q.REGDATE) AS REGDATE,Q.STATUS FROM QNABOARD Q JOIN MEMBER M ON Q.MEMBER_ID=M.MEMBER_ID JOIN QNA_CATEGORY C ON Q.CATEGORY_NO=C.NO
AND category_no=#{categoryno}
AND status=#{status}
ORDER BY Q.REGDATE DESC, Q.NO DESC OFFSET #{start} ROWS FETCH NEXT 10 ROWS ONLY

SELECT count(*) FROM QNABOARD Q JOIN MEMBER M ON Q.MEMBER_ID=M.MEMBER_ID JOIN QNA_CATEGORY C ON Q.CATEGORY_NO=C.NO
AND category_no=#{categoryno}
AND status=#{status}

mapper.update:
